using System.Text.Json;
using Tamaneen.SharedKernel;

namespace Tamaneen.Crisis.Rules;

public enum CrisisScriptKind
{
    High = 0,
    Critical = 1,
    SystemFailure = 2,
}

/// <summary>
/// The fixed, clinically approved texts the patient sees on the crisis screen (P06). Never generated by AI.
/// Placeholders: {emergency_number}, {support_line}.
/// </summary>
public sealed class CrisisScripts
{
    private readonly Dictionary<(CrisisScriptKind, string), string> _texts;

    private CrisisScripts(string version, Dictionary<(CrisisScriptKind, string), string> texts)
    {
        Version = version;
        _texts = texts;
    }

    public string Version { get; }

    public static CrisisScripts Load(Stream json)
    {
        var dto = JsonSerializer.Deserialize<Dto>(json, RulePack.JsonOptions) ?? throw new InvalidDataException("Crisis scripts are empty.");
        if (string.IsNullOrWhiteSpace(dto.Version) || dto.Scripts is null)
        {
            throw new InvalidDataException("Crisis scripts need a version.");
        }

        var texts = new Dictionary<(CrisisScriptKind, string), string>();
        foreach (var kind in Enum.GetValues<CrisisScriptKind>())
        {
            foreach (var language in SupportedLanguages.All)
            {
                if (!dto.Scripts.TryGetValue(kind, out var byLanguage) || !byLanguage.TryGetValue(language, out var text) || string.IsNullOrWhiteSpace(text))
                {
                    throw new InvalidDataException($"Crisis script {kind} is missing in '{language}'. Both languages are required.");
                }

                if (!text.Contains("{emergency_number}", StringComparison.Ordinal))
                {
                    throw new InvalidDataException($"Crisis script {kind}/{language} must show {{emergency_number}}.");
                }

                texts[(kind, language)] = text;
            }
        }

        return new CrisisScripts(dto.Version!, texts);
    }

    public string Render(CrisisScriptKind kind, string language, string emergencyNumber, string supportLine)
    {
        var text = _texts[(kind, SupportedLanguages.Normalize(language))];
        return text.Replace("{emergency_number}", emergencyNumber, StringComparison.Ordinal)
                   .Replace("{support_line}", supportLine, StringComparison.Ordinal);
    }

    public static CrisisScriptKind KindFor(RiskLevel level) => level >= RiskLevel.Critical ? CrisisScriptKind.Critical : CrisisScriptKind.High;

    private sealed class Dto
    {
        public string? Version { get; set; }

        public Dictionary<CrisisScriptKind, Dictionary<string, string>>? Scripts { get; set; }
    }
}
